package ApanaCollegePattern2;

public class Flyodstrianglewithnumbers {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int n=5;
		
		int num=1;
		for(int i=1;i<=n;i++)
		{
			for(int j=i;j>0;j--)
			{
				System.out.print(num+" ");
				num++;
				
				}
			System.out.println();	
			
		}


	}

}
